const c=JSON.parse(JSON.stringify($('Article context').first().json));if(c.enrich_earnings)c.earnings=$input.first().json.earnings||null;
const allowed=(c.candidates||[]).slice(0,Math.max(1,Math.min(2,Number(c.cfg?.max_candidates_per_event||2))));
const compactEvent={title:String(c.event.title||'').slice(0,600),url:c.event.url,snippet:String(c.event.snippet||'').slice(0,1800),published_on:c.event.published_on,evidence_scope:c.event.evidence_scope,source_name:c.event.source_name,article_source_url:c.event.article_evidence?.url,article_text_excerpt:String(c.event.article_evidence?.text||'').slice(0,5000)};
